-- Vocabulary V2 step by step (IELTS-V2 v1.1.0): five guided steps and one mixed check, in the Lesson 6 format
-- (LEARN FIRST worked example, an explanation for every answer). Auto-marked, so filed as reading tasks; every item is
-- mapped to the vocabulary subskill it practises. Owner instruction 2026-10-28 13:01 (Asia/Bishkek): 'Go next'.
-- Named-student pilot with requires_review; nothing is released. Source: docs/ielts/practice/TARGETED_VOCABULARY_01.json.
do $steps$
declare art constant text := '

- - - - - - - - - - - - - - - - - - - -

THE DATA (fictional, for practice)

DATA 1. Electricity generated from three sources, one country, 2000-2020 (% of total electricity)
Year: 2000 | 2005 | 2010 | 2015 | 2020
Coal: 58% | 57% | 49% | 36% | 22%
Gas: 30% | 31% | 33% | 33% | 32%
Wind and solar: 2% | 4% | 11% | 24% | 41%

DATA 2. Average weekly hours spent on four activities by teenagers, one city, 2010 and 2020 (hours per week)
Social media: 2010 6 hours, 2020 18 hours
Sport: 2010 8 hours, 2020 6 hours
Reading: 2010 5 hours, 2020 3 hours
Homework: 2010 10 hours, 2020 10 hours';
begin
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r64-v1','0.1.0','Vocabulary V2 step 1 of 6: Meet the trend words','reading','guided_practice','Read LEARN FIRST and the worked example. Then choose the meaning of each word or phrase. You do not need the data yet.','Trend words carry size and speed: ''soar'' and ''plummet'' are big and fast; ''level off'' means it stops changing.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "What does ''soar'' mean?", "accepted_answers": ["A"], "taxonomy_node_id": "1772911e-5c6a-4d17-b07f-336595e2f8ef", "supporting_node_id": "c90adeab-a6e3-473a-8e53-b86f6738ccbd", "options": [{"value": "A", "label": "A  rise very fast by a large amount"}, {"value": "B", "label": "B  rise slowly and steadily"}, {"value": "C", "label": "C  stay the same"}, {"value": "D", "label": "D  go up and down"}]}, {"id": "q2", "prompt": "What does ''plummet'' mean?", "accepted_answers": ["D"], "taxonomy_node_id": "1772911e-5c6a-4d17-b07f-336595e2f8ef", "supporting_node_id": "c90adeab-a6e3-473a-8e53-b86f6738ccbd", "options": [{"value": "A", "label": "A  fall slightly"}, {"value": "B", "label": "B  become larger than another figure"}, {"value": "C", "label": "C  stop changing"}, {"value": "D", "label": "D  fall very fast by a large amount"}]}, {"id": "q3", "prompt": "What does ''level off'' mean?", "accepted_answers": ["C"], "taxonomy_node_id": "1772911e-5c6a-4d17-b07f-336595e2f8ef", "supporting_node_id": "c90adeab-a6e3-473a-8e53-b86f6738ccbd", "options": [{"value": "A", "label": "A  go up and down irregularly"}, {"value": "B", "label": "B  fall to zero"}, {"value": "C", "label": "C  stop changing and stay at about the same level"}, {"value": "D", "label": "D  reach the highest point"}]}, {"id": "q4", "prompt": "What does ''fluctuate'' mean?", "accepted_answers": ["A"], "taxonomy_node_id": "1772911e-5c6a-4d17-b07f-336595e2f8ef", "supporting_node_id": "c90adeab-a6e3-473a-8e53-b86f6738ccbd", "options": [{"value": "A", "label": "A  go up and down irregularly"}, {"value": "B", "label": "B  stay exactly the same"}, {"value": "C", "label": "C  fall once and then stop"}, {"value": "D", "label": "D  rise every year"}]}, {"id": "q5", "prompt": "What does ''overtake'' mean?", "accepted_answers": ["B"], "taxonomy_node_id": "1772911e-5c6a-4d17-b07f-336595e2f8ef", "supporting_node_id": "c90adeab-a6e3-473a-8e53-b86f6738ccbd", "options": [{"value": "A", "label": "A  reach the highest point"}, {"value": "B", "label": "B  become larger than something that was larger before"}, {"value": "C", "label": "C  fall below zero"}, {"value": "D", "label": "D  make up part of a total"}]}, {"id": "q6", "prompt": "What does ''account for'' mean in ''Coal accounted for 58% of electricity''?", "accepted_answers": ["D"], "taxonomy_node_id": "1772911e-5c6a-4d17-b07f-336595e2f8ef", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "options": [{"value": "A", "label": "A  become larger than"}, {"value": "B", "label": "B  explain the reason for"}, {"value": "C", "label": "C  pay for"}, {"value": "D", "label": "D  make up a part of the total"}]}]'::jsonb,'{"scope": "Targeted IELTS vocabulary exercise; not a full paper.", "suggested_minutes": 6, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-vocabulary-targeted-focus-v1", "teacher_notes": "1 A, ''Soar'' is a big, fast rise: sales soared from 5% to 40% in two years.\n2 D, ''Plummet'' is a big, fast fall. A two-point fall is never ''plummeted''.\n3 C, ''Level off'' means the figure stops rising or falling and stays about the same.\n4 A, ''Fluctuate'' means move up and down without a steady direction: prices fluctuated between 20 and 25 dollars.\n5 B, ''Overtake'' compares two figures: one passes the other.\n6 D, ''Account for'' here means make up or form part of a total. (In other contexts it can mean ''explain'', but not with a percentage.)\nRead each explanation, then use the word or phrase in a sentence of your own.", "focus": "Use a suitable vocabulary range: learn the meaning and strength of trend language for Writing Task 1."}'::jsonb || jsonb_build_object('passage', 'LEARN FIRST: trend words have a size

Writing Task 1 rewards words that match the size of a change. Learn the strength, not only the direction.
- rise / increase / climb: go up
- fall / decrease / decline: go down
- soar: rise very fast by a large amount
- plummet: fall very fast by a large amount
- level off / remain stable: stop changing
- fluctuate: go up and down irregularly
- peak at: reach the highest point
- overtake: become larger than something that was larger before
- account for / make up: be a particular part of a total

WORKED EXAMPLE
A share goes from 30% to 32% in twenty years. ''Soared'' is wrong: two points is tiny.
Better: ''rose marginally'' or ''remained relatively stable''.

Now choose the meaning of six words.'),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_VOCABULARY_01.json 0.1.0"}'::jsonb,'804e4e7b2ae236c8dd35cee8b55d75851055dd21b80335348968ae9f600fb5ce',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r65-v1','0.1.0','Vocabulary V2 step 2 of 6: Is the word strong enough?','reading','guided_practice','Read LEARN FIRST and the worked example. Then use the data to choose the description whose strength matches each change.','Look at the numbers first, then choose the word. A big, fast change needs a strong word; a tiny change needs a weak one.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Coal, 2015 to 2020 (36% to 22%). The share of coal ...", "accepted_answers": ["B"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  soared"}, {"value": "B", "label": "B  fell sharply"}, {"value": "C", "label": "C  fell marginally"}, {"value": "D", "label": "D  levelled off"}]}, {"id": "q2", "prompt": "Gas, 2010 to 2020 (33% to 32%). The share of gas ...", "accepted_answers": ["C"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  fell sharply"}, {"value": "B", "label": "B  plummeted"}, {"value": "C", "label": "C  remained almost stable"}, {"value": "D", "label": "D  fluctuated wildly"}]}, {"id": "q3", "prompt": "Wind and solar, 2000 to 2005 (2% to 4%). The share ...", "accepted_answers": ["D"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  plummeted"}, {"value": "B", "label": "B  soared"}, {"value": "C", "label": "C  levelled off"}, {"value": "D", "label": "D  rose slightly"}]}, {"id": "q4", "prompt": "Wind and solar, 2015 to 2020 (24% to 41%). The share ...", "accepted_answers": ["A"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  soared"}, {"value": "B", "label": "B  fell steadily"}, {"value": "C", "label": "C  rose marginally"}, {"value": "D", "label": "D  remained stable"}]}, {"id": "q5", "prompt": "Coal, 2000 to 2005 (58% to 57%). The share of coal ...", "accepted_answers": ["C"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  rose slightly"}, {"value": "B", "label": "B  plummeted"}, {"value": "C", "label": "C  remained almost unchanged"}, {"value": "D", "label": "D  fluctuated"}]}, {"id": "q6", "prompt": "Sport, 2010 to 2020 (8 to 6 hours a week). Time spent on sport ...", "accepted_answers": ["B"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  halved"}, {"value": "B", "label": "B  fell slightly, by two hours"}, {"value": "C", "label": "C  plummeted"}, {"value": "D", "label": "D  remained unchanged"}]}]'::jsonb,'{"scope": "Targeted IELTS vocabulary exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-vocabulary-targeted-focus-v1", "teacher_notes": "1 B, fell sharply: 14 points in five years is a large, fast fall. ''Marginally'' is far too weak.\n2 C, remained almost stable: one point in ten years is a tiny change.\n3 D, rose slightly: two points is a small rise in total share, even though the figure doubled.\n4 A, soared: 17 points in five years is the biggest, fastest change in the data.\n5 C, remained almost unchanged: a one-point fall is tiny; ''rose'' is the wrong direction.\n6 B, fell slightly, by two hours: 8 to 6 is a small fall, not half (that would be 4).\nRead each explanation, then use the word or phrase in a sentence of your own.", "focus": "Choose precise vocabulary: match the strength of trend language to the size of the change in the data."}'::jsonb || jsonb_build_object('passage', 'LEARN FIRST: numbers first, then the word

1. Read the two numbers. How big is the change?
2. Is it fast (a short time) or slow (a long time)?
3. Choose the word with the same strength:
   tiny: marginally, slightly, remained stable
   clear: steadily, considerably
   very large and fast: soared, plummeted, rose or fell sharply

WORKED EXAMPLE
Coal, 2010 to 2015: 49% to 36%. A fall of 13 points in five years.
''Fell slightly'' is too weak. ''Plummeted to zero'' is false. ''Fell sharply'' matches. -> fell sharply

Now match six changes. Use DATA 1 and DATA 2 below.' || art),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_VOCABULARY_01.json 0.1.0"}'::jsonb,'3592e7afc9f187e57f1c6b61fad924d706d8acb16b25a42aeb6ddf82c946e770',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r66-v1','0.1.0','Vocabulary V2 step 3 of 6: Trend grammar','reading','guided_practice','Read LEARN FIRST and the worked example. Then choose the word that makes each sentence correct.','Verb + adverb (rose sharply), adjective + noun + ''in'' (a sharp rise in), peak AT, account FOR, as MUCH as for amounts.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "There was a sharp fall ______ the share of coal after 2005.", "accepted_answers": ["C"], "taxonomy_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "supporting_node_id": "cefbe886-39b2-4efa-9123-6ad04ea0f631", "options": [{"value": "A", "label": "A  for"}, {"value": "B", "label": "B  on"}, {"value": "C", "label": "C  in"}, {"value": "D", "label": "D  at"}]}, {"id": "q2", "prompt": "The share of gas peaked ______ 33%.", "accepted_answers": ["B"], "taxonomy_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "supporting_node_id": "cefbe886-39b2-4efa-9123-6ad04ea0f631", "options": [{"value": "A", "label": "A  in"}, {"value": "B", "label": "B  at"}, {"value": "C", "label": "C  on"}, {"value": "D", "label": "D  by"}]}, {"id": "q3", "prompt": "Coal accounted ______ 58% of electricity in 2000.", "accepted_answers": ["A"], "taxonomy_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "supporting_node_id": "cefbe886-39b2-4efa-9123-6ad04ea0f631", "options": [{"value": "A", "label": "A  for"}, {"value": "B", "label": "B  with"}, {"value": "C", "label": "C  on"}, {"value": "D", "label": "D  to"}]}, {"id": "q4", "prompt": "Wind and solar power rose ______ between 2010 and 2020.", "accepted_answers": ["C"], "taxonomy_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "supporting_node_id": "c3f8634b-03c1-4218-b582-05afc24e4eff", "options": [{"value": "A", "label": "A  a steep"}, {"value": "B", "label": "B  steep"}, {"value": "C", "label": "C  steeply"}, {"value": "D", "label": "D  steepness"}]}, {"id": "q5", "prompt": "There was a ______ increase in wind and solar power.", "accepted_answers": ["B"], "taxonomy_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "supporting_node_id": "c3f8634b-03c1-4218-b582-05afc24e4eff", "options": [{"value": "A", "label": "A  dramatically"}, {"value": "B", "label": "B  dramatic"}, {"value": "C", "label": "C  dramatise"}, {"value": "D", "label": "D  drama"}]}, {"id": "q6", "prompt": "In 2020, teenagers spent three times as ______ time on social media as in 2010.", "accepted_answers": ["D"], "taxonomy_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "supporting_node_id": "cefbe886-39b2-4efa-9123-6ad04ea0f631", "options": [{"value": "A", "label": "A  most"}, {"value": "B", "label": "B  more"}, {"value": "C", "label": "C  many"}, {"value": "D", "label": "D  much"}]}]'::jsonb,'{"scope": "Targeted IELTS vocabulary exercise; not a full paper.", "suggested_minutes": 7, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-vocabulary-targeted-focus-v1", "teacher_notes": "1 C, in: we say a rise in or a fall in something, so ''a sharp fall in the share of coal''.\n2 B, at: a figure peaks at its highest number, so ''peaked at 33%''.\n3 A, for: account for a share of a total, so ''accounted for 58% of electricity''.\n4 C, steeply: after the verb ''rose'' you need an adverb.\n5 B, dramatic: before the noun ''increase'' you need an adjective.\n6 D, much: time is uncountable, so ''as much ... as''. ''As many'' is for countable things.\nRead each explanation, then use the word or phrase in a sentence of your own.", "focus": "Word classes and collocation: use trend vocabulary with the correct grammar and prepositions."}'::jsonb || jsonb_build_object('passage', 'LEARN FIRST: two patterns and four small words

Pattern 1, VERB + ADVERB: Wind power rose sharply.
Pattern 2, ADJECTIVE + NOUN + in: There was a sharp rise in wind power.
Small words that are often wrong:
- a rise / fall IN something
- peak AT a number
- account FOR a share
- twice / three times as MUCH (amounts, time) / as MANY (countable things) as

WORKED EXAMPLE
''There was a ______ increase in exports.''  The gap is before a noun, so it needs an adjective: considerable.
''Exports increased ______.''  The gap is after a verb, so it needs an adverb: considerably.

Now choose six words.'),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_VOCABULARY_01.json 0.1.0"}'::jsonb,'0991c49c813e1602f5d6313a06942615e9863b18b4fd1b8831b2d6b7291883b6',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r67-v1','0.1.0','Vocabulary V2 step 4 of 6: Compare the figures','reading','guided_practice','Read LEARN FIRST and the worked example. Then use the data to choose the comparison that is accurate.','Check the arithmetic: twice = x2, three times = x3, a quarter = 25%, a third = 33%, two fifths = 40%, half = 50%.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "In 2020, teenagers spent ______ on social media as on homework.", "accepted_answers": ["D"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  three times as long"}, {"value": "B", "label": "B  half as long"}, {"value": "C", "label": "C  exactly twice as long"}, {"value": "D", "label": "D  almost twice as long"}]}, {"id": "q2", "prompt": "In 2010, the time teenagers spent on homework was ______ the time they spent reading.", "accepted_answers": ["C"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  half"}, {"value": "B", "label": "B  three times"}, {"value": "C", "label": "C  double"}, {"value": "D", "label": "D  the same as"}]}, {"id": "q3", "prompt": "In 2020, wind and solar power accounted for ______ of electricity.", "accepted_answers": ["C"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  nearly half"}, {"value": "B", "label": "B  just under a quarter"}, {"value": "C", "label": "C  just over two fifths"}, {"value": "D", "label": "D  roughly a third"}]}, {"id": "q4", "prompt": "In 2015, coal accounted for ______ of electricity.", "accepted_answers": ["A"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  just over a third"}, {"value": "B", "label": "B  exactly a third"}, {"value": "C", "label": "C  just under a quarter"}, {"value": "D", "label": "D  nearly half"}]}, {"id": "q5", "prompt": "Between 2015 and 2020, wind and solar power ______ coal.", "accepted_answers": ["B"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "c90adeab-a6e3-473a-8e53-b86f6738ccbd", "options": [{"value": "A", "label": "A  accounted for"}, {"value": "B", "label": "B  overtook"}, {"value": "C", "label": "C  levelled off"}, {"value": "D", "label": "D  peaked at"}]}, {"id": "q6", "prompt": "Time spent on sport, ______ time on social media, fell between 2010 and 2020.", "accepted_answers": ["A"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  unlike"}, {"value": "B", "label": "B  as well as"}, {"value": "C", "label": "C  like"}, {"value": "D", "label": "D  similar to"}]}]'::jsonb,'{"scope": "Targeted IELTS vocabulary exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-vocabulary-targeted-focus-v1", "teacher_notes": "1 D, almost twice as long: 18 hours and 10 hours. Twice would be 20, so ''almost twice'' is accurate.\n2 C, double: 10 hours and 5 hours. 10 = 2 x 5.\n3 C, just over two fifths: 41%. Two fifths is 40%. ''Nearly half'' would need about 48 or 49%.\n4 A, just over a third: 36%. A third is about 33%, so 36% is just over.\n5 B, overtook: in 2015 wind and solar (24%) was smaller than coal (36%); in 2020 it (41%) was larger than coal (22%).\n6 A, unlike: sport fell (8 to 6) but social media rose (6 to 18), so the trends are different.\nRead each explanation, then use the word or phrase in a sentence of your own.", "focus": "Choose precise vocabulary: compare figures accurately with multiples, fractions and approximations."}'::jsonb || jsonb_build_object('passage', 'LEARN FIRST: check the arithmetic

Comparisons must be exact enough to be true.
- twice as much = x2, three times as much = x3, half as much = ÷2
- a quarter = 25%, a third = about 33%, two fifths = 40%, a half = 50%
- just under = a little less; just over = a little more; nearly / almost = a little less
- overtake = A was smaller than B, then became larger

WORKED EXAMPLE
DATA 2, 2010: homework 10 hours, sport 8 hours.
''Teenagers spent twice as long on homework as on sport.'' 10 is not 2 x 8.  -> wrong
''Teenagers spent slightly more time on homework than on sport.''  -> accurate

Now choose six accurate comparisons.' || art),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_VOCABULARY_01.json 0.1.0"}'::jsonb,'d5ad4825bb1d3df20f570649c3a8f8041f5500e2f5cd12eb7ec0478e18e0d655',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r68-v1','0.1.0','Vocabulary V2 step 5 of 6: Accurate, or what is wrong?','reading','guided_practice','Read LEARN FIRST and the worked example. Then check each sentence against the data and choose what is wrong with it, if anything.','Check three things in order: the FIGURES, the STRENGTH of the words, and the GRAMMAR.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "''Homework remained unchanged at ten hours a week.''", "accepted_answers": ["A"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  accurate"}, {"value": "B", "label": "B  a wrong figure or fact"}, {"value": "C", "label": "C  the wrong strength (too strong or too weak)"}, {"value": "D", "label": "D  a grammar mistake"}]}, {"id": "q2", "prompt": "''Time spent reading plummeted between 2010 and 2020.''", "accepted_answers": ["C"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  accurate"}, {"value": "B", "label": "B  a wrong figure or fact"}, {"value": "C", "label": "C  the wrong strength (too strong or too weak)"}, {"value": "D", "label": "D  a grammar mistake"}]}, {"id": "q3", "prompt": "''Coal accounted for 49% of electricity in 2015.''", "accepted_answers": ["B"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  accurate"}, {"value": "B", "label": "B  a wrong figure or fact"}, {"value": "C", "label": "C  the wrong strength (too strong or too weak)"}, {"value": "D", "label": "D  a grammar mistake"}]}, {"id": "q4", "prompt": "''There was a slight fall on time spent on sport.''", "accepted_answers": ["D"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "options": [{"value": "A", "label": "A  accurate"}, {"value": "B", "label": "B  a wrong figure or fact"}, {"value": "C", "label": "C  the wrong strength (too strong or too weak)"}, {"value": "D", "label": "D  a grammar mistake"}]}, {"id": "q5", "prompt": "''Gas overtook coal in 2015.''", "accepted_answers": ["B"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  accurate"}, {"value": "B", "label": "B  a wrong figure or fact"}, {"value": "C", "label": "C  the wrong strength (too strong or too weak)"}, {"value": "D", "label": "D  a grammar mistake"}]}, {"id": "q6", "prompt": "''The share of gas fluctuated slightly between 30% and 33%.''", "accepted_answers": ["A"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  accurate"}, {"value": "B", "label": "B  a wrong figure or fact"}, {"value": "C", "label": "C  the wrong strength (too strong or too weak)"}, {"value": "D", "label": "D  a grammar mistake"}]}]'::jsonb,'{"scope": "Targeted IELTS vocabulary exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-vocabulary-targeted-focus-v1", "teacher_notes": "1 A, accurate: homework was 10 hours in 2010 and 10 hours in 2020.\n2 C, the wrong strength: reading fell from 5 to 3 hours. That is a fall of two hours, not a plunge.\n3 B, a wrong figure: coal was 49% in 2010, but 36% in 2015.\n4 D, a grammar mistake: a fall IN something, not ''on''.\n5 B, a wrong fact: in 2015 gas was 33% and coal was 36%, so gas was still smaller.\n6 A, accurate: gas moved between 30 and 33% (30, 31, 33, 33, 32), small changes up and down.\nRead each explanation, then use the word or phrase in a sentence of your own.", "focus": "Choose precise vocabulary: check a description against data for errors of fact, strength and grammar."}'::jsonb || jsonb_build_object('passage', 'LEARN FIRST: check figures, strength, grammar

Before you hand in a Task 1 answer, check every sentence three ways:
1. FIGURES: are the numbers and the years right?
2. STRENGTH: does the word match the size of the change?
3. GRAMMAR: rose sharply / a sharp rise in / peaked at / accounted for.

WORKED EXAMPLE
''Gas rose marginally, peaking at 33% in 2010 and 2015.''
Figures: gas was 33% in 2010 and 2015, the highest. Strength: 30 to 33 is marginal. Grammar: peaking at. -> accurate

Now check six sentences.' || art),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_VOCABULARY_01.json 0.1.0"}'::jsonb,'2094692cb19aefa6cb2812cb1f659603421cc0ef16317af909ca20bb8e21916a',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r69-v1','0.1.0','Vocabulary V2 step 6 of 6: Mixed check: new data','reading','independent_check','Read LEARN FIRST, which gives you NEW data. Then answer six questions on it. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Use the whole routine on new data: numbers first, then the word with the right strength, comparisons checked, grammar checked.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Between 2015 and 2023, visits by under-18s ______.", "accepted_answers": ["D"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  halved"}, {"value": "B", "label": "B  tripled"}, {"value": "C", "label": "C  rose marginally"}, {"value": "D", "label": "D  doubled"}]}, {"id": "q2", "prompt": "Visits by people aged 18 to 64 ______.", "accepted_answers": ["A"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  remained almost unchanged"}, {"value": "B", "label": "B  doubled"}, {"value": "C", "label": "C  soared"}, {"value": "D", "label": "D  plummeted"}]}, {"id": "q3", "prompt": "In 2023, adults aged 18 to 64 still ______ the largest group of visitors.", "accepted_answers": ["B"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "c90adeab-a6e3-473a-8e53-b86f6738ccbd", "options": [{"value": "A", "label": "A  fluctuated"}, {"value": "B", "label": "B  made up"}, {"value": "C", "label": "C  peaked at"}, {"value": "D", "label": "D  overtook"}]}, {"id": "q4", "prompt": "In 2015, there were ______ visits by people aged 65 and over than by under-18s.", "accepted_answers": ["D"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  the same number of"}, {"value": "B", "label": "B  more"}, {"value": "C", "label": "C  twice as many"}, {"value": "D", "label": "D  fewer"}]}, {"id": "q5", "prompt": "There was a sharp rise ______ visits by people aged 65 and over.", "accepted_answers": ["C"], "taxonomy_node_id": "dded4435-86bc-4f98-a822-5796ab2c9540", "supporting_node_id": "cefbe886-39b2-4efa-9123-6ad04ea0f631", "options": [{"value": "A", "label": "A  at"}, {"value": "B", "label": "B  of"}, {"value": "C", "label": "C  in"}, {"value": "D", "label": "D  on"}]}, {"id": "q6", "prompt": "In 2023, under-18s accounted for ______ of all visits.", "accepted_answers": ["C"], "taxonomy_node_id": "07c8e6ee-7ec1-412a-aa64-d2f74df41a6a", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  roughly a quarter"}, {"value": "B", "label": "B  nearly two thirds"}, {"value": "C", "label": "C  just under a third"}, {"value": "D", "label": "D  just over half"}]}]'::jsonb,'{"scope": "Targeted IELTS vocabulary exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-vocabulary-targeted-focus-v1", "teacher_notes": "1 D, doubled: 40 to 80 thousand. 80 = 2 x 40.\n2 A, remained almost unchanged: 120 to 118 thousand is a tiny fall.\n3 B, made up: 118 of 258 thousand visits, more than any other group. ''Make up'' describes part of a total.\n4 D, fewer: 30 thousand compared with 40 thousand.\n5 C, in: we say a rise in something, so ''a sharp rise in visits''.\n6 C, just under a third: 80 of 258 thousand is about 31%. A third is about 33%.\nRead each explanation, then use the word or phrase in a sentence of your own.", "focus": "Trend and comparison language on new data: strength, multiples, proportions and grammar."}'::jsonb || jsonb_build_object('passage', 'LEARN FIRST: new data, same routine

NEW DATA (fictional, for practice)
Visitors to a city museum by age group (thousands of visits)
Under 18: 2015: 40 | 2023: 80
18 to 64: 2015: 120 | 2023: 118
65 and over: 2015: 30 | 2023: 60
Total: 2015: 190 | 2023: 258

ROUTINE
1. Numbers first: how big is each change?
2. Choose the word with the right strength.
3. Check comparisons with arithmetic.
4. Check the grammar: a rise IN, account FOR.

WORKED EXAMPLE
''Visits by people aged 65 and over ______ between 2015 and 2023.'' 30 to 60 = x2. -> doubled

Now answer six questions on your own.'),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_VOCABULARY_01.json 0.1.0"}'::jsonb,'ecabc23f8f5064aae973cacefe95181d16ca77f4f1a380f767325de38de9e8a9',true) on conflict (code) do nothing;
end $steps$;
